import {
  createElement,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ChangeEvent,
  type DragEvent,
  type ReactNode
} from 'react';
import { Modal, Spinner } from '@docs-front/ui';
import {
  Button,
  Flex,
  SegmentedControlItem,
  SegmentedControlRoot,
  colors
} from '@bichon/ds';
import { useQuery } from '@tanstack/react-query';
import { HTTPError } from 'ky';
import { File as FileIcon, Info, LoaderCircle, Upload, X } from 'lucide-react';

import { postFileValidate } from '@/api/products/validate';
import { useModal } from '@/hooks/useModal';
import {
  getProductsFilesOptions,
  getProductsQueryOptions
} from '@/query/options/products';
import { StyledSupportingText } from '@/routes/_authenticated/c/-components/HwpWarningModal/HwpWarningModal.style';
import { InvalidPdfFileModal } from '@/routes/_authenticated/c/-components/MainPrompt/InvalidPdfFileModal';
import { InvalidXmlFileModal } from '@/routes/_authenticated/c/-components/MainPrompt/InvalidXmlFileModal';
import { XmlCharacterLimitModal } from '@/routes/_authenticated/c/-components/MainPrompt/XmlCharacterLimitModal';
import ExistingDocumentsTable, {
  type SelectedDocumentInfo as ExistingSelectedDocumentInfo
} from '@/routes/_authenticated/f/upload/-components/ExistingDocumentsTable/ExistingDocumentsTable';
import {
  StyledDropzone,
  StyledDropzoneMainText,
  StyledDropzoneSubText,
  StyledFileIcon,
  StyledFileItem,
  StyledFileList,
  StyledFileName,
  StyledFileSize,
  StyledSpinningIcon,
  StyledInfoBanner,
  StyledSectionTitle,
  StyledStepHeader,
  StyledStepSubtitle,
  StyledTemplateName
} from '@/routes/_authenticated/f/upload/-upload.style';

const MAX_FILES = 3;
const MAX_FILE_SIZE = 30 * 1024 * 1024;
const ACCEPTED_EXTENSIONS = ['.pdf', '.docx', '.hwp', '.hwpx'];

type DocumentFilter = 'form' | 'draft';

interface StartSelectedDocumentInfo {
  type: 'export' | 'draftProduct' | 'draftExport';
  id: string;
  productContents: string;
}

interface Step3Props {
  hasUpload: boolean;
  onUploadChange: (val: boolean) => void;
  selectedDocument: StartSelectedDocumentInfo | null;
  onSelectDocument: (doc: StartSelectedDocumentInfo | null) => void;
  referenceFiles: File[];
  onReferenceFilesChange: (files: File[]) => Promise<void>;
  onReferenceFilesProcessingChange: (isProcessing: boolean) => void;
  templateName: string;
}

function validateFile(
  file: File
): { isValid: boolean; error?: 'unsupported' | 'filesize' } {
  if (file.size > MAX_FILE_SIZE) {
    return { isValid: false, error: 'filesize' };
  }

  const fileName = file.name.toLowerCase();
  const isValidExtension = ACCEPTED_EXTENSIONS.some((extension) =>
    fileName.endsWith(extension)
  );

  if (!isValidExtension) {
    return { isValid: false, error: 'unsupported' };
  }

  return { isValid: true };
}

function formatFileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes}B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)}KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)}MB`;
}

export function Step3Upload({
  hasUpload,
  onUploadChange,
  selectedDocument,
  onSelectDocument,
  referenceFiles,
  onReferenceFilesChange,
  onReferenceFilesProcessingChange,
  templateName
}: Step3Props) {
  const modal = useModal();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const currentFilesRef = useRef(referenceFiles);
  const isMountedRef = useRef(false);
  const [isDragOver, setIsDragOver] = useState(false);
  const [docFilter, setDocFilter] = useState<DocumentFilter>('form');
  const [validatingFiles, setValidatingFiles] = useState<Set<string>>(
    new Set()
  );
  const [persistingCount, setPersistingCount] = useState(0);

  const exportQueryOptions = getProductsFilesOptions({
    page: 0,
    size: 100,
    fileType: 'EXPORT'
  });
  const { data: exportData, isLoading: isExportLoading } =
    useQuery(exportQueryOptions);
  const exportDocuments = useMemo(
    () => exportData?.data?.exports?.content ?? [],
    [exportData]
  );
  const availableExportDocuments = useMemo(
    () => exportDocuments.filter((doc) => doc.status !== 'FAILED'),
    [exportDocuments]
  );
  const completedExportDocuments = useMemo(
    () => availableExportDocuments.filter((doc) => doc.status === 'COMPLETED'),
    [availableExportDocuments]
  );

  const { data: draftExportData, isLoading: isDraftExportLoading } = useQuery(
    getProductsFilesOptions({
      page: 0,
      size: 100,
      fileType: 'DRAFT_EXPORT'
    })
  );
  const draftExportDocuments = useMemo(
    () => draftExportData?.data?.exports?.content ?? [],
    [draftExportData]
  );
  const availableDraftExportDocuments = useMemo(
    () => draftExportDocuments.filter((doc) => doc.status !== 'FAILED'),
    [draftExportDocuments]
  );
  const completedDraftExportDocuments = useMemo(
    () =>
      availableDraftExportDocuments.filter((doc) => doc.status === 'COMPLETED'),
    [availableDraftExportDocuments]
  );

  const { data: draftProducts = [], isLoading: isDraftLoading } = useQuery(
    getProductsQueryOptions()
  );
  const availableDraftProducts = useMemo(
    () =>
      draftProducts.filter((product) =>
        ['PENDING', 'PROGRESS', 'COMPLETED'].includes(
          product.generationStatus ?? ''
        )
      ),
    [draftProducts]
  );
  const completedDraftProducts = useMemo(
    () =>
      availableDraftProducts.filter(
        (product) => product.generationStatus === 'COMPLETED'
      ),
    [availableDraftProducts]
  );

  const selectedExistingDocument = useMemo<ExistingSelectedDocumentInfo | null>(
    () => {
      if (!selectedDocument) return null;

      if (selectedDocument.type === 'export') {
        const document = completedExportDocuments.find(
          (doc) => doc.productFileId === selectedDocument.id
        );

        return document ? { type: 'export', document } : null;
      }

      if (selectedDocument.type === 'draftExport') {
        const document = completedDraftExportDocuments.find(
          (doc) => doc.productFileId === selectedDocument.id
        );

        return document ? { type: 'draftExport', document } : null;
      }

      const product = completedDraftProducts.find(
        (draft) => draft.id === selectedDocument.id
      );

      if (!product) {
        return null;
      }

      return {
        type: 'draftProduct',
        product: {
          id: selectedDocument.id,
          itemName: product?.itemName ?? null,
          content: selectedDocument.productContents
        }
      };
    },
    [
      completedDraftExportDocuments,
      completedDraftProducts,
      completedExportDocuments,
      selectedDocument,
    ]
  );

  const filteredExportDocuments = useMemo(
    () => (docFilter === 'form' ? availableExportDocuments : []),
    [availableExportDocuments, docFilter]
  );

  const filteredDraftProducts = useMemo(
    () => (docFilter === 'draft' ? availableDraftProducts : []),
    [availableDraftProducts, docFilter]
  );

  const filteredDraftExportDocuments = useMemo(
    () => (docFilter === 'draft' ? availableDraftExportDocuments : []),
    [availableDraftExportDocuments, docFilter]
  );

  const isProcessingFiles = validatingFiles.size > 0 || persistingCount > 0;

  useEffect(() => {
    currentFilesRef.current = referenceFiles;
  }, [referenceFiles]);

  useEffect(() => {
    onReferenceFilesProcessingChange(isProcessingFiles);
  }, [isProcessingFiles, onReferenceFilesProcessingChange]);

  useEffect(() => {
    isMountedRef.current = true;

    return () => {
      isMountedRef.current = false;
      onReferenceFilesProcessingChange(false);
    };
  }, [onReferenceFilesProcessingChange]);

  useEffect(() => {
    if (!selectedDocument) return;
    if (
      isExportLoading ||
      isDraftExportLoading ||
      isDraftLoading
    ) {
      return;
    }

    if (selectedDocument.type === 'export') {
      const isValid = completedExportDocuments.some(
        (doc) => doc.productFileId === selectedDocument.id
      );
      if (!isValid) onSelectDocument(null);
      return;
    }

    if (selectedDocument.type === 'draftExport') {
      const isValid = completedDraftExportDocuments.some(
        (doc) => doc.productFileId === selectedDocument.id
      );
      if (!isValid) onSelectDocument(null);
      return;
    }

    const isValid = completedDraftProducts.some(
      (product) => product.id === selectedDocument.id
    );
    if (!isValid) {
      onSelectDocument(null);
    }
  }, [
    completedDraftExportDocuments,
    completedDraftProducts,
    completedExportDocuments,
    isDraftExportLoading,
    isDraftLoading,
    isExportLoading,
    onSelectDocument,
    selectedDocument,
  ]);

  const openAlertDialog = useCallback(
    (title: string, description: ReactNode) => {
      modal.openModal(({ isOpen, onClose }) => (
        <Modal isOpen={isOpen} onClose={onClose}>
          <Modal.Header title={title} />
          <Modal.Body>{description}</Modal.Body>
          <Modal.Footer>
            <Modal.ConfirmButton onClick={onClose}>확인</Modal.ConfirmButton>
          </Modal.Footer>
        </Modal>
      ));
    },
    [modal]
  );

  const openUploadErrorDialog = useCallback(
    (message: string) => {
      openAlertDialog(
        '파일 업로드에 실패했습니다',
        <StyledSupportingText>{message}</StyledSupportingText>
      );
    },
    [openAlertDialog]
  );

  const syncReferenceFiles = useCallback(
    async (nextFiles: File[]) => {
      const previousFiles = currentFilesRef.current;
      currentFilesRef.current = nextFiles;
      onUploadChange(nextFiles.length > 0);
      setPersistingCount((prev) => prev + 1);

      try {
        await onReferenceFilesChange(nextFiles);
      } catch (error) {
        currentFilesRef.current = previousFiles;
        onUploadChange(previousFiles.length > 0);
        openUploadErrorDialog(
          '참고자료 저장에 실패했습니다. 잠시 후 다시 시도해주세요.'
        );
        throw error;
      } finally {
        if (isMountedRef.current) {
          setPersistingCount((prev) => Math.max(prev - 1, 0));
        }
      }
    },
    [onReferenceFilesChange, onUploadChange, openUploadErrorDialog]
  );

  const handleValidationError = useCallback(
    (error: unknown) => {
      let status: number | undefined;

      if (error instanceof HTTPError) {
        status = error.response?.status;

        if (
          status === 413 &&
          error.message?.includes('XML character limit exceeded')
        ) {
          modal.openModal(({ isOpen, onClose }) =>
            createElement(XmlCharacterLimitModal, {
              isOpen,
              onClose,
              showPdfConversion: true
            })
          );
          return;
        }

        if (status === 400 && error.message === '유효한 XML 형식이 아닙니다.') {
          modal.openModal(({ isOpen, onClose }) =>
            createElement(InvalidXmlFileModal, { isOpen, onClose })
          );
          return;
        }

        if (
          status === 400 &&
          error.message?.includes('텍스트를 추출할 수 없는 PDF')
        ) {
          modal.openModal(({ isOpen, onClose }) =>
            createElement(InvalidPdfFileModal, {
              isOpen,
              onClose,
              type: 'image'
            })
          );
          return;
        }

        if (status === 400 && error.message?.includes('has not been decrypted')) {
          modal.openModal(({ isOpen, onClose }) =>
            createElement(InvalidPdfFileModal, {
              isOpen,
              onClose,
              type: 'encrypted'
            })
          );
          return;
        }
      }

      openUploadErrorDialog(
        status === 413
          ? '파일 크기가 너무 커 업로드할 수 없습니다.'
          : '파일 검증 중 오류가 발생했습니다. 잠시 후 다시 시도해주세요.'
      );
    },
    [modal, openUploadErrorDialog]
  );

  const addFiles = useCallback(
    (newFiles: File[]) => {
      const currentFiles = currentFilesRef.current;
      const remainingSlots = MAX_FILES - currentFiles.length;
      if (remainingSlots <= 0) return;

      const filesToAdd = newFiles.slice(0, remainingSlots);
      const validFiles: File[] = [];

      const isDuplicateFile = (file: File) =>
        [...currentFiles, ...validFiles].some(
          (existing) =>
            existing.name === file.name && existing.size === file.size
        );

      for (const file of filesToAdd) {
        const validation = validateFile(file);

        if (validation.isValid) {
          if (isDuplicateFile(file)) {
            openAlertDialog(
              '중복된 파일입니다',
              <StyledSupportingText>
                동일한 파일은 한 번만 첨부할 수 있습니다.
              </StyledSupportingText>
            );
          } else {
            validFiles.push(file);
          }
          continue;
        }

        if (validation.error === 'filesize') {
          openAlertDialog(
            '파일 크기를 초과했습니다',
            <StyledSupportingText>
              30MB 이하 파일만 업로드할 수 있습니다.
            </StyledSupportingText>
          );
          continue;
        }

        openAlertDialog(
          '지원하지 않는 파일 형식입니다',
          <StyledSupportingText>
            pdf, docx, hwp, hwpx 파일만 업로드할 수 있습니다.
          </StyledSupportingText>
        );
      }

      if (validFiles.length === 0) return;

      const nextFiles = [...currentFiles, ...validFiles];
      void syncReferenceFiles(nextFiles).catch(() => undefined);

      for (const file of validFiles) {
        const fileKey = `${file.name}-${file.size}`;

        setValidatingFiles((prev) => new Set(prev).add(fileKey));

        postFileValidate(file, 'REFERENCE')
          .catch(async (error) => {
            const filteredFiles = currentFilesRef.current.filter(
              (existing) =>
                !(
                  existing.name === file.name &&
                  existing.size === file.size &&
                  existing.lastModified === file.lastModified
                )
            );

            try {
              await syncReferenceFiles(filteredFiles);
            } catch {
              return;
            }

            if (isMountedRef.current) {
              handleValidationError(error);
            }
          })
          .finally(() => {
            if (!isMountedRef.current) return;

            setValidatingFiles((prev) => {
              const next = new Set(prev);
              next.delete(fileKey);
              return next;
            });
          });
      }
    },
    [handleValidationError, openAlertDialog, syncReferenceFiles]
  );

  const removeFile = useCallback(
    (index: number) => {
      const nextFiles = currentFilesRef.current.filter(
        (_, fileIndex) => fileIndex !== index
      );
      void syncReferenceFiles(nextFiles).catch(() => undefined);
    },
    [syncReferenceFiles]
  );

  const handleDocumentUpload = useCallback(
    (info: ExistingSelectedDocumentInfo | null) => {
      if (!info) {
        onSelectDocument(null);
        return;
      }

      if (info.type === 'export') {
        onSelectDocument({
          type: 'export',
          id: info.document.productFileId,
          productContents: ''
        });
        return;
      }

      if (info.type === 'draftExport') {
        onSelectDocument({
          type: 'draftExport',
          id: info.document.productFileId,
          productContents: ''
        });
        return;
      }

      onSelectDocument({
        type: 'draftProduct',
        id: info.product.id,
        productContents: info.product.content
      });
    },
    [onSelectDocument]
  );

  const handleDrop = useCallback(
    (event: DragEvent) => {
      event.preventDefault();
      setIsDragOver(false);
      addFiles(Array.from(event.dataTransfer.files));
    },
    [addFiles]
  );

  const handleDragOver = useCallback((event: DragEvent) => {
    event.preventDefault();
    setIsDragOver(true);
  }, []);

  const handleDragLeave = useCallback((event: DragEvent) => {
    event.preventDefault();
    setIsDragOver(false);
  }, []);

  const handleDropzoneClick = useCallback(() => {
    if (referenceFiles.length >= MAX_FILES) return;
    fileInputRef.current?.click();
  }, [referenceFiles.length]);

  const handleFileInputChange = useCallback(
    (event: ChangeEvent<HTMLInputElement>) => {
      if (event.target.files) {
        addFiles(Array.from(event.target.files));
      }

      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    },
    [addFiles]
  );

  const isLoading =
    isExportLoading ||
    isDraftExportLoading ||
    isDraftLoading;
  const hasUploadedFiles = hasUpload || referenceFiles.length > 0;

  return (
    <Flex direction="column" gap={32} width="100%">
      <StyledStepHeader>
        <StyledTemplateName>&lsquo;{templateName}&rsquo;</StyledTemplateName>
        <StyledStepSubtitle>
          작성을 위한 자료를 업로드해주세요
        </StyledStepSubtitle>
      </StyledStepHeader>

      <StyledInfoBanner>
        <Info size={16} />
        <span>
          기존에 만들었던 다른 사업계획서 파일 혹은 이외 파일들을 업로드하는
          단계입니다.
        </span>
      </StyledInfoBanner>

      <Flex direction="column" gap={16} width="100%">
        <StyledSectionTitle>파일 업로드하기</StyledSectionTitle>

        <StyledDropzone
          $isDragOver={isDragOver}
          $disabled={referenceFiles.length >= MAX_FILES}
          onDrop={handleDrop}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onClick={handleDropzoneClick}
        >
          <input
            ref={fileInputRef}
            type="file"
            accept={ACCEPTED_EXTENSIONS.join(',')}
            multiple
            style={{ display: 'none' }}
            onChange={handleFileInputChange}
          />
          <Flex
            direction="column"
            gap={8}
            alignItems="center"
            justify="center"
          >
            <Upload
              size={24}
              color={
                hasUploadedFiles ? colors.textAccent : colors.textTertiary
              }
            />
            <StyledDropzoneMainText>
              클릭하여 파일을 선택하거나 여기로 드래그해주세요
            </StyledDropzoneMainText>
            <StyledDropzoneSubText>
              (pdf, docx, hwp, hwpx에 한하여 30mb 이내 {MAX_FILES}개까지
              첨부 가능)
            </StyledDropzoneSubText>
          </Flex>
        </StyledDropzone>

        {referenceFiles.length > 0 && (
          <StyledFileList>
            {referenceFiles.map((file, index) => {
              const isValidating = validatingFiles.has(
                `${file.name}-${file.size}`
              );

              return (
                <StyledFileItem key={`${file.name}-${file.size}-${index}`}>
                  {isValidating ? (
                    <StyledSpinningIcon>
                      <LoaderCircle size={16} color={colors.textTertiary} />
                    </StyledSpinningIcon>
                  ) : (
                    <StyledFileIcon>
                      <FileIcon size={16} color={colors.textTertiary} />
                    </StyledFileIcon>
                  )}
                  <StyledFileName>{file.name}</StyledFileName>
                  <StyledFileSize>{formatFileSize(file.size)}</StyledFileSize>
                  <Button
                    type="button"
                    variant="text"
                    size="small"
                    onClick={() => removeFile(index)}
                  >
                    <X size={16} color={colors.textSecondary} />
                  </Button>
                </StyledFileItem>
              );
            })}
          </StyledFileList>
        )}
      </Flex>

      <Flex direction="column" gap={16} width="100%">
        <Flex justify="space-between" alignItems="center" width="100%">
          <StyledSectionTitle>기존 작성 문서 불러오기</StyledSectionTitle>
          <SegmentedControlRoot
            size="small"
            value={docFilter}
            onValueChange={(value) => setDocFilter(value as DocumentFilter)}
          >
            <SegmentedControlItem value="form">양식</SegmentedControlItem>
            <SegmentedControlItem value="draft">초안</SegmentedControlItem>
          </SegmentedControlRoot>
        </Flex>

        {isLoading ? (
          <Flex justify="center" alignItems="center" style={{ padding: '40px 0' }}>
            <Spinner size={24} />
          </Flex>
        ) : (
          <ExistingDocumentsTable
            key={docFilter}
            exportDocuments={filteredExportDocuments}
            draftExportDocuments={filteredDraftExportDocuments}
            draftProducts={filteredDraftProducts}
            selectedDocument={selectedExistingDocument}
            onUpload={handleDocumentUpload}
          />
        )}
      </Flex>
    </Flex>
  );
}
