import { createFileRoute, Navigate } from '@tanstack/react-router';

import { Step3Upload } from '@/routes/_authenticated/start/-components/steps/Step3Upload';
import { useStartFlow } from '@/routes/_authenticated/start/-startFlow.context';

export const Route = createFileRoute('/_authenticated/start/upload/')({
  component: RouteComponent
});

function RouteComponent() {
  const {
    selectedDraftTemplate,
    hasUpload,
    setHasUpload,
    selectedDocument,
    setSelectedDocument,
    referenceFiles,
    setReferenceFiles,
    setReferenceFilesProcessing,
    templateName
  } = useStartFlow();

  if (!selectedDraftTemplate) {
    return <Navigate to="/start/template" replace />;
  }

  return (
    <Step3Upload
      hasUpload={hasUpload}
      onUploadChange={setHasUpload}
      selectedDocument={selectedDocument}
      onSelectDocument={setSelectedDocument}
      referenceFiles={referenceFiles}
      onReferenceFilesChange={setReferenceFiles}
      onReferenceFilesProcessingChange={setReferenceFilesProcessing}
      templateName={templateName}
    />
  );
}
